import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Load brushed-metal texture
  const baseTexture = ctx.textureLoader.load(config.assets.imageUrl);
  baseTexture.colorSpace = THREE.SRGBColorSpace;

  // Create material with TSL texture node
  const textureNode = texture(baseTexture);
  const material = new MeshBasicNodeMaterial();
  material.colorNode = textureNode;
  material.transparent = true;

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply position from config
  const { scenePosition, sceneRotation, sceneScale } = config;
  if (scenePosition) {
    mesh.position.fromArray(scenePosition);
  }
  if (sceneRotation) {
    mesh.rotation.fromArray(sceneRotation);
  }
  if (sceneScale) {
    mesh.scale.fromArray(sceneScale);
  }

  // Render text content via fontAtlas
  if (config.textContent && config.textContent.length > 0) {
    const textContent = config.textContent[0];
    const textMesh = ctx.fontAtlas.createText({
      text: textContent.text,
      fontSize: textContent.fontSize,
      fontFamily: 'Lora',
      fontWeight: textContent.fontWeight,
      color: new THREE.Color(config.colors.ink),
    });

    // Position text slightly above plane
    textMesh.position.z = 0.01;
    mesh.add(textMesh);
  }

  // Setup resource cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (baseTexture) baseTexture.dispose();
  };

  mesh.userData.handlers = {};

  return mesh;
}
